export const CINEMATIQUE_LIBRARY = CINEMATIQUE_TECHNIQUES;

export function getCinematiqueById(id: string): CinematiqueTechnique | undefined {
  return CINEMATIQUE_TECHNIQUES.find((t) => t.id === id);
}

export function getCinematiqueByCategory(category: CinematiqueCategory): CinematiqueTechnique[] {
  return CINEMATIQUE_TECHNIQUES.filter((t) => t.category === category);
}

export function searchCinematiqueTechniques(
  query: string = '',
  category: CinematiqueCategory | 'ALL' = 'ALL'
): CinematiqueTechnique[] {
  const q = query.trim().toLowerCase();
  return CINEMATIQUE_TECHNIQUES.filter((t) => {
    const matchCat = category === 'ALL' || t.category === category;
    if (!matchCat) return false;
    if (!q) return true;
    return (
      t.name.toLowerCase().includes(q) ||
      t.nameZh.toLowerCase().includes(q) ||
      t.categoryZh.toLowerCase().includes(q) ||
      t.description.toLowerCase().includes(q) ||
      t.promptTemplate.toLowerCase().includes(q)
    );
  });
}

export function getCinematiqueCategories(): Array<{
  key: CinematiqueCategory;
  labelZh: string;
  count: number;
}> {
  const categories: CinematiqueCategory[] = [
    'Camera Work',
    'Lighting',
    'Composition',
    'Editing',
    'Storytelling',
    'Visual Effects & Promptable FX',
    'Genres & Styles',
  ];

  return categories.map((cat) => ({
    key: cat,
    labelZh:
      cat === 'Camera Work'
        ? '摄影运镜与机位景别'
        : cat === 'Lighting'
        ? '电影布光与光影氛围'
        : cat === 'Composition'
        ? '构图美学与空间几何'
        : cat === 'Editing'
        ? '剪辑节奏与转场语法'
        : cat === 'Storytelling'
        ? '叙事修辞与戏剧视听'
        : cat === 'Visual Effects & Promptable FX'
        ? '光学质感与镜头特效'
        : '电影流派与作者美学',
    count: CINEMATIQUE_TECHNIQUES.filter((t) => t.category === cat).length,
  }));
}

export function formatCinematiqueForPrompt(technique: CinematiqueTechnique, subject: string = 'Subject'): string {
  if (!technique.promptTemplate) return '';
  return technique.promptTemplate.replace(/\[Subject\]/gi, subject);
}
